Variable Rel : TH -> PML.pstate -> PML.pstate -> Z -> bvmap 5 word -> Prop.
Variable EXpost : TH -> eghost -> PML.pstate -> mem -> Z -> PML.pstate -> Z -> eghost -> Prop.      (* [comment removed for export] *)
Hypothesis CALLEE : forall th : TH, ptrans_gbxE L HI WFin BBin (PAin th) (PAout th) CPC CSCR (Args th) (Rel th) (EXpost th).
