Definition ptrans_prex (th : TH) (g : eghost) (R : bvmap 5 word) (M : mem) (cr : credit) (pst : PML.pstate) : Prop := ltac2:(Rpl.RP.run_i (rplG ()) 6 "S20!1+3!1,4|600;|30;$th;R/TH;$g;R+9$R;R!2'8!1,4|21;0$M;R%~R0!1+5!1+3!1,41$cr;R':$pst;R+1!2+@!8/Args;#6/LBo;#4#3/paddr;/vaddr;/eaddr;#1!2+@!4/PAin;#6#3/paddr;#1!2+@!1/WFin;#1!2+@!3'B#3/LBo;#1!2+@!2/BBin;#1/Bv;!2+@!2'C#3/vaddr;!2+@!3'D#3/eaddr;,E!2+@!2'F/g0;#3!2+@!4'J#3/vaddr;/s2addr;#5!2+@!1'K#3!2+@!2'L#1#5!5'N/L;#2#1!2'O/KXv;!2'P/L;#5/BXv;").
